async fn plugin_call(
    connection: &zbus::Connection,
    plugin_id: &str,
    method_name: &str,
    arguments: &Value,
    operation_id: &str,
    mut transport: crate::invocation::CallMetadata,
    deadline: crate::invocation::Deadline,
) -> Result<Value, LungsError> { … }

fn method_call_error(error: zbus::Error, operation_id: &str) -> LungsError { … }

fn refusal(error: &zbus::Error) -> bool { … }

pub fn validate_engine_receipt(
    plugin_id: &str,
    method_name: &str,
    method: &MethodDecl,
    value: &Value,
) -> Result<(), LungsError> { … }

fn receipt(
    plugin_id: &str,
    method_name: &str,
    method: &MethodDecl,
    result: Value,
    operation_id: &str,
) -> Result<CallReceipt, LungsError> { … }

